import { DEFAULT_LANG, type LangCode } from './languages';

/**
 * i18n layer for STATIC UI text only — commands, buttons, section labels,
 * errors, and the disclaimer. These are fixed and finite, so they live here as
 * plain strings: zero token cost, instant, and reviewable (important for the
 * medical disclaimer, which must read correctly in every language).
 *
 * The DYNAMIC medicine content (uses, side effects, warnings) is NOT here — it
 * is generated by the LLM directly in the user's language (see awareness.prompt).
 *
 * To add a language: add a Strings block keyed by its LangCode. Done.
 */

type WarningKey = 'pregnancy' | 'liver' | 'kidney' | 'alcohol' | 'children' | 'elderly';

export interface Strings {
  disclaimer: string;
  welcome: string;
  help: string;
  usage: (used: number, limit: number, remaining: number) => string;
  rateLimit: (hours: number, limit: number) => string;
  lowConfidence: (reason: string | null) => string;
  notAMedicine: string;
  sendPhoto: string;
  sendImage: string;
  downloadFailed: string;
  extractionFailed: string;
  imageTooLarge: (mb: string) => string;
  somethingWrong: string;
  purposeQuestion: (name: string, ingredients: string) => string;
  purposeTypePrompt: string;
  purposeLabels: Record<string, string>;
  typeLabel: string;
  skipLabel: string;
  analysis: {
    contains: string;
    drugClass: string;
    howItWorks: string;
    commonUses: string;
    commonSideEffects: string;
    seriousSideEffects: string;
    warnings: string;
    warningKeys: Record<WarningKey, string>;
    interactions: string;
    overdoseAwareness: string;
    fdaVerified: string;
  };
}

/**
 * Shown on /start and /language BEFORE we know the user's language, so it is
 * intentionally bilingual. The picker buttons themselves are the language names
 * in their own script, so the choice is unambiguous.
 */
export const LANGUAGE_PROMPT =
  '🌐 *Please choose your language*\n' +
  'ದಯವಿಟ್ಟು ನಿಮ್ಮ ಭಾಷೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ';

function escapeMd(text: string): string {
  return text.replace(/([*_`\[\]])/g, '\\$1');
}

