/* --------------------------------- Registry -------------------------------- */

const STRINGS: Record<LangCode, Strings> = { en, kn };

/** Get the string table for a language (falls back to the default language). */
export function t(lang: LangCode): Strings {
  return STRINGS[lang] ?? STRINGS[DEFAULT_LANG];
}
